import { Dialog, Transition } from "@headlessui/react";
import { Fragment } from "react";
import { DayPicker } from "react-day-picker";
import "react-day-picker/dist/style.css"; 
import { motion } from "framer-motion";

interface CalendarModalProps {
  isOpen: boolean;
  closeModal: () => void;
}

const CalendarModal: React.FC<CalendarModalProps> = ({ isOpen, closeModal }) => {
  return (
    <Transition appear show={isOpen} as={Fragment}>
      <Dialog as="div" className="relative z-50" onClose={closeModal}>
        <div className="fixed inset-0 bg-black bg-opacity-50 backdrop-blur-md" />
        <div className="fixed inset-0 flex items-center justify-center p-4">
          <Transition.Child
            as={Fragment}
            enter="transition transform duration-300 ease-out"
            enterFrom="opacity-0 scale-95"
            enterTo="opacity-100 scale-100"
            leave="transition transform duration-200 ease-in"
            leaveFrom="opacity-100 scale-100"
            leaveTo="opacity-0 scale-95"
          >
            <Dialog.Panel className="w-full max-w-fit rounded-xl bg-[#1E1E2E] p-6 shadow-2xl text-white border border-gray-700">
              
              <div className="flex justify-between items-center mb-4">
                <h2 className="text-lg font-semibold">Select a Date</h2>
                <button
                  onClick={closeModal}
                  className="text-gray-400 hover:text-white transition  duration-200 px-2 py-1 rounded-md hover:bg-gray-700"
                >
                  ✕
                </button>
              </div>
              <motion.div
                initial={{ opacity: 0, y: 20 }}
                animate={{ opacity: 1, y: 0 }}
                transition={{ duration: 0.4, ease: "easeOut" }}
                className="w-fit mx-auto"
              >
                <DayPicker
                  mode="single"
                  className="rounded-lg bg-[#2A2A36] w-fit mx-auto px-8 py-3 text-white"
               
                />
              </motion.div>
            </Dialog.Panel>
          </Transition.Child>
        </div>
      </Dialog>
    </Transition>
  );
};

export default CalendarModal;
