import { Dialog, Transition } from "@headlessui/react";
import { Fragment } from "react";
import {
  FaMicrophone,
  FaVideo,
  FaPhoneSlash,
  FaComments,
  FaCommentDots,
  FaVolumeUp,
} from "react-icons/fa";

interface Call {
  id: string;
  name: string;
  time: string;
  type: "audio" | "video";
}

interface CallWindowProps {
  selectedCall?: Call;
  onClose: () => void;
}

const CallWindow: React.FC<CallWindowProps> = ({ selectedCall, onClose }) => {
  if (!selectedCall) return null;

  return (
    <>
      {selectedCall.type === "video" ? (
        <Transition
          appear
          show={!!selectedCall}
          as={Fragment}
          enter="transition duration-100 ease-out"
          enterFrom="transform scale-95 opacity-0"
          enterTo="transform scale-100 opacity-100"
          leave="transition duration-75 ease-out"
          leaveFrom="transform scale-100 opacity-100"
          leaveTo="transform scale-95 opacity-0"
        >
          <Dialog as="div" className="relative z-50" onClose={onClose}>
            <div className="fixed inset-0 bg-black bg-opacity-60 backdrop-blur-md" />
            <div className="fixed inset-0 flex items-center justify-center p-4">
              <Dialog.Panel className="w-full max-w-4xl h-[85vh] bg-[#121212] text-white rounded-xl shadow-xl p-6 flex flex-col">
                <Dialog.Title className="text-xl font-semibold text-center">
                  Video Call with {selectedCall.name}
                </Dialog.Title>
                <div className="flex-1 flex items-center justify-center bg-gray-800 rounded-lg mt-4">
                  <p className="text-gray-400">Live Video Call Feed</p>
                </div>
                <div className="mt-6 flex justify-center space-x-4">
                  <button className="p-3 bg-gray-700 rounded-full hover:bg-gray-600">
                    <FaMicrophone size={20} />
                  </button>
                  <button className="p-3 bg-gray-700 rounded-full hover:bg-gray-600">
                    <FaVideo size={20} />
                  </button>
                  <button
                    className="p-3 bg-red-600 rounded-full hover:bg-red-500"
                    onClick={onClose} // ✅ Fixed: onClick instead of onClose
                  >
                    <FaPhoneSlash size={20} />
                  </button>
                  <button className="p-3 bg-gray-700 rounded-full hover:bg-gray-600">
                    <FaComments size={20} />
                  </button>
                </div>
              </Dialog.Panel>
            </div>
          </Dialog>
        </Transition>
      ) : (
        // Audio Call Modal
        <Transition
          appear
          show={!!selectedCall}
          as={Fragment}
          enter="transition duration-100 ease-out"
          enterFrom="transform scale-95 opacity-0"
          enterTo="transform scale-100 opacity-100"
          leave="transition duration-75 ease-out"
          leaveFrom="transform scale-100 opacity-100"
          leaveTo="transform scale-95 opacity-0"
        >
          <Dialog as="div" className="relative z-50" onClose={onClose}>
            <div className="fixed inset-0 bg-black bg-opacity-60 backdrop-blur-md" />
            <div className="fixed inset-0 flex items-center justify-center p-4">
              <Dialog.Panel className="w-full max-w-sm bg-[#121212] text-white rounded-xl shadow-xl p-6 flex flex-col items-center">
                <Dialog.Title className="text-xl font-semibold text-center">
                  Voice Call with {selectedCall.name}
                </Dialog.Title>
                <div className="mt-6 w-28 h-28 bg-gray-700 rounded-full flex items-center justify-center">
                  <span className="text-gray-400">{selectedCall.name[0]}</span>
                </div>
                <p className="mt-4 text-gray-400">00:15 • Calling...</p>
                <div className="mt-6 flex justify-center space-x-4">
                  <button className="p-3 bg-gray-700 rounded-full hover:bg-gray-600">
                    <FaMicrophone size={20} />
                  </button>
                  <button className="p-3 bg-gray-700 rounded-full hover:bg-gray-600">
                    <FaVolumeUp size={20} />
                  </button>
                  <button
                    className="p-3 bg-red-600 rounded-full hover:bg-red-500"
                    onClick={onClose} // ✅ Fixed: onClick instead of onClose
                  >
                    <FaPhoneSlash size={20} />
                  </button>
                  <button className="p-3 bg-gray-700 rounded-full hover:bg-gray-600">
                    <FaCommentDots size={20} />
                  </button>
                </div>
              </Dialog.Panel>
            </div>
          </Dialog>
        </Transition>
      )}
    </>
  );
};

export default CallWindow;
